CREATE TABLE IF NOT EXISTS raising_versions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, checkpoint_json TEXT NOT NULL, checkpoint_hash TEXT NOT NULL, training_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS raising_active_versions (user_id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES raising_versions(id), updated_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS raising_versions_immutable BEFORE UPDATE ON raising_versions BEGIN SELECT RAISE(ABORT, 'immutable checkpoint'); END;
CREATE TABLE IF NOT EXISTS raising_training_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')), parent_version_id TEXT NOT NULL REFERENCES raising_versions(id), rows_json TEXT NOT NULL, created_at INTEGER NOT NULL, lease_until INTEGER NOT NULL DEFAULT 0, lease_token TEXT, attempts INTEGER NOT NULL DEFAULT 0, completed_at INTEGER, result_json TEXT, error TEXT, UNIQUE(user_id,idempotency_key));
CREATE TRIGGER IF NOT EXISTS raising_training_input_immutable BEFORE UPDATE OF rows_json,parent_version_id,user_id,idempotency_key ON raising_training_jobs BEGIN SELECT RAISE(ABORT, 'immutable training input'); END;
CREATE UNIQUE INDEX IF NOT EXISTS raising_version_training ON raising_versions(training_id) WHERE training_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS raising_interval_claims (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('TRAIN','EVAL')),start INTEGER NOT NULL,end INTEGER NOT NULL,CHECK(start<=end));
CREATE INDEX IF NOT EXISTS raising_interval_user ON raising_interval_claims(user_id,start,end);
CREATE TRIGGER IF NOT EXISTS raising_interval_no_leak BEFORE INSERT ON raising_interval_claims WHEN EXISTS (SELECT 1 FROM raising_interval_claims WHERE user_id=NEW.user_id AND start<=NEW.end AND end>=NEW.start AND (kind='EVAL' OR NEW.kind='EVAL')) BEGIN SELECT RAISE(ABORT, 'INTERVAL_ALREADY_EXPOSED'); END;
CREATE TABLE IF NOT EXISTS raising_evaluations (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,training_id TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT,candles_json TEXT NOT NULL,created_at INTEGER NOT NULL,error TEXT);
CREATE TRIGGER IF NOT EXISTS raising_session_exposure AFTER INSERT ON raising_sessions WHEN json_array_length(NEW.data_json,'$.bars')>0 BEGIN INSERT INTO raising_interval_claims VALUES ('session:'||NEW.id,NEW.user_id,'TRAIN',json_extract(NEW.data_json,'$.bars[0].time'),json_extract(NEW.data_json,'$.bars[#-1].time')); END;
CREATE TRIGGER IF NOT EXISTS raising_session_history_immutable BEFORE UPDATE OF data_json,user_id ON raising_sessions BEGIN SELECT RAISE(ABORT,'immutable session history'); END;
CREATE TRIGGER IF NOT EXISTS raising_claim_update BEFORE UPDATE ON raising_interval_claims BEGIN SELECT RAISE(ABORT,'immutable exposure'); END;
CREATE TRIGGER IF NOT EXISTS raising_claim_delete BEFORE DELETE ON raising_interval_claims BEGIN SELECT RAISE(ABORT,'immutable exposure'); END;
CREATE TABLE IF NOT EXISTS raising_observation_assignments (user_id TEXT NOT NULL,observation_hash TEXT NOT NULL,split TEXT NOT NULL CHECK(split IN ('train','validation')),PRIMARY KEY(user_id,observation_hash));
CREATE TRIGGER IF NOT EXISTS raising_assignment_conflict BEFORE INSERT ON raising_observation_assignments WHEN EXISTS (SELECT 1 FROM raising_observation_assignments WHERE user_id=NEW.user_id AND observation_hash=NEW.observation_hash AND split<>NEW.split) BEGIN SELECT RAISE(ABORT,'GLOBAL_SPLIT_CONFLICT'); END;
CREATE TRIGGER IF NOT EXISTS raising_assignment_update BEFORE UPDATE ON raising_observation_assignments BEGIN SELECT RAISE(ABORT,'immutable assignment'); END;
CREATE TRIGGER IF NOT EXISTS raising_assignment_delete BEFORE DELETE ON raising_observation_assignments BEGIN SELECT RAISE(ABORT,'immutable assignment'); END;
INSERT OR IGNORE INTO raising_observation_assignments SELECT j.user_id,h.value,s.key FROM raising_training_jobs j,json_each(j.result_json,'$.split_manifest') s,json_each(s.value,'$.observation_hashes') h WHERE j.status='COMPLETED' AND s.key IN ('train','validation');
CREATE TRIGGER IF NOT EXISTS raising_job_assignments BEFORE UPDATE OF status ON raising_training_jobs WHEN NEW.status='COMPLETED' BEGIN SELECT CASE WHEN EXISTS (SELECT 1 FROM raising_observation_assignments a WHERE a.user_id=NEW.user_id AND NOT EXISTS (SELECT 1 FROM json_each(NEW.result_json,'$.split_manifest') s,json_each(s.value,'$.observation_hashes') h WHERE s.key=a.split AND h.value=a.observation_hash)) THEN RAISE(ABORT,'GLOBAL_REPLAY_REQUIRED') END; INSERT OR IGNORE INTO raising_observation_assignments SELECT NEW.user_id,h.value,s.key FROM json_each(NEW.result_json,'$.split_manifest') s,json_each(s.value,'$.observation_hashes') h WHERE s.key IN ('train','validation'); END;
CREATE TABLE IF NOT EXISTS raising_split_registry (user_id TEXT PRIMARY KEY,manifest_json TEXT NOT NULL,validation_start INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS raising_split_conflict BEFORE INSERT ON raising_split_registry WHEN EXISTS (SELECT 1 FROM raising_split_registry WHERE user_id=NEW.user_id AND validation_start<>NEW.validation_start) BEGIN SELECT RAISE(ABORT,'GLOBAL_SPLIT_CONFLICT'); END;
CREATE TRIGGER IF NOT EXISTS raising_split_update BEFORE UPDATE ON raising_split_registry BEGIN SELECT RAISE(ABORT,'immutable global split'); END;
CREATE TRIGGER IF NOT EXISTS raising_split_delete BEFORE DELETE ON raising_split_registry BEGIN SELECT RAISE(ABORT,'immutable global split'); END;
INSERT OR IGNORE INTO raising_split_registry SELECT user_id,json_extract(result_json,'$.split_manifest'),json_extract(result_json,'$.split_manifest.validation.start') FROM raising_training_jobs WHERE status='COMPLETED' AND json_extract(result_json,'$.split_manifest.validation.start') IS NOT NULL ORDER BY created_at,id;
INSERT OR IGNORE INTO raising_interval_claims SELECT 'session:'||id,user_id,'TRAIN',json_extract(data_json,'$.bars[0].time'),json_extract(data_json,'$.bars[#-1].time') FROM raising_sessions WHERE json_array_length(data_json,'$.bars')>0;
